SELECT  FROM building_unit bu JOIN building b ON b.building_id=bu.building_id

    bu.building_id=#{buildingId}
    AND bu.status=#{status}
    AND b.community_id IN #{scopeId}AND 1 = 0

ORDER BY b.building_no,bu.unit_no,bu.building_unit_id

SELECT  FROM building_unit bu JOIN building b ON b.building_id=bu.building_id
WHERE bu.building_unit_id=#{buildingUnitId}
AND b.community_id IN #{scopeId}AND 1 = 0
